/* ------------------------- FINAL CERTIFICATION TEST ------------------------- */
/* 100 questions, 12 topics. Each has a difficulty (1 foundation, 2 practitioner,
   3 expert); the array is sorted by difficulty so the test gets harder as you go. */
PGM.FINAL_TEST = [
/* ============================== SQL (9) ============================== */
{ topic: 'SQL', difficulty: 1, type: 'predict',
  q: 'projects has 24 rows; 6 of them have end_date = NULL. What does this return?',
  code: `SELECT COUNT(*) AS all_rows, COUNT(end_date) AS with_end
FROM projects;`,
  options: ['24 | 24', '24 | 18', '18 | 18', '24 | 6'], answer: 1,
  explain: 'COUNT(*) counts rows; COUNT(expression) counts only rows where the expression is NOT NULL. This is the most common reason two "row counts" disagree in reports. Use COUNT(*) FILTER (WHERE end_date IS NULL) to count the NULLs explicitly.' },
{ topic: 'SQL', difficulty: 1, type: 'tf',
  q: 'In PostgreSQL, the expression NULL = NULL evaluates to TRUE.',
  answer: false,
  explain: 'Any ordinary comparison with NULL yields NULL (unknown), and WHERE treats NULL as "not true", so the row is filtered out. Use IS NULL, or IS NOT DISTINCT FROM when you want NULL-safe equality (NULL IS NOT DISTINCT FROM NULL is TRUE).' },
{ topic: 'SQL', difficulty: 1, type: 'mcq',
  q: 'You want only departments whose AVERAGE salary is above 90,000. Which clause filters on the aggregate?',
  options: ['WHERE AVG(salary) > 90000', 'HAVING AVG(salary) > 90000', 'ORDER BY AVG(salary) > 90000', 'GROUP BY AVG(salary) > 90000'], answer: 1,
  explain: 'WHERE runs before grouping, row by row, so aggregates are not available there (it raises "aggregate functions are not allowed in WHERE"). HAVING runs after GROUP BY and filters whole groups. Put row-level filters in WHERE (cheaper — fewer rows reach the aggregate) and group-level filters in HAVING.' },
{ topic: 'SQL', difficulty: 2, type: 'bug',
  q: 'This query fails. Why?',
  code: `SELECT department_id, first_name, COUNT(*)
FROM employees
GROUP BY department_id;`,
  options: ['COUNT(*) cannot be combined with GROUP BY', 'first_name is neither grouped nor aggregated, so PostgreSQL cannot pick one value per group', 'department_id must be wrapped in MAX()', 'GROUP BY must come before FROM'], answer: 1,
  explain: 'Every non-aggregated column in the SELECT list must be in GROUP BY (or be functionally dependent on a grouped primary key). A department has many first names; PostgreSQL refuses to pick one arbitrarily (unlike old MySQL). Either add first_name to GROUP BY, aggregate it (string_agg(first_name, \', \')), or remove it.' },
{ topic: 'SQL', difficulty: 2, type: 'predict',
  q: 'Some customers have never ordered. Which customers does this return?',
  code: `SELECT c.id, c.name
FROM customers c
LEFT JOIN orders o ON o.customer_id = c.id
WHERE o.status = 'paid';`,
  options: ['All 500 customers, with NULLs for those without paid orders', 'Only customers that have at least one paid order (one row per paid order)', 'Only customers with no orders', 'An error: WHERE cannot reference the right side of a LEFT JOIN'], answer: 1,
  explain: 'For customers without orders, o.status is NULL and NULL = \'paid\' is not true, so the WHERE clause removes them — the LEFT JOIN silently becomes an INNER JOIN. To keep all customers and only attach paid orders, move the condition into the join: LEFT JOIN orders o ON o.customer_id = c.id AND o.status = \'paid\'.' },
{ topic: 'SQL', difficulty: 2, type: 'bug',
  q: 'Goal: employees who manage nobody. The query returns ZERO rows even though most employees are not managers. Why?',
  code: `SELECT id, first_name
FROM employees
WHERE id NOT IN (SELECT manager_id FROM employees);`,
  options: ['NOT IN does not work with subqueries', 'The subquery returns NULLs (department heads have manager_id NULL); x NOT IN (..., NULL) is never TRUE', 'id and manager_id have different data types', 'The subquery must be correlated'], answer: 1,
  explain: 'x NOT IN (a, b, NULL) expands to x &lt;&gt; a AND x &lt;&gt; b AND x &lt;&gt; NULL; the last term is NULL, so the whole condition is NULL or FALSE — never TRUE. Use NOT EXISTS (SELECT 1 FROM employees m WHERE m.manager_id = e.id), which is NULL-safe and plans as an efficient anti-join.' },
{ topic: 'SQL', difficulty: 3, type: 'predict',
  q: 'What are the values of r, dr and rn for the THIRD row (salary 90)?',
  code: `SELECT s,
       RANK()       OVER (ORDER BY s DESC) AS r,
       DENSE_RANK() OVER (ORDER BY s DESC) AS dr,
       ROW_NUMBER() OVER (ORDER BY s DESC) AS rn
FROM (VALUES (100), (100), (90)) v(s);`,
  options: ['r=2, dr=2, rn=3', 'r=3, dr=2, rn=3', 'r=3, dr=3, rn=3', 'r=2, dr=3, rn=2'], answer: 1,
  explain: 'The two 100s tie: RANK gives both 1 and then skips to 3 (gaps after ties); DENSE_RANK gives both 1 and continues with 2 (no gaps); ROW_NUMBER always numbers 1,2,3 (ties broken arbitrarily unless ORDER BY is unique). Choose based on whether "top 3" should include ties.' },
{ topic: 'SQL', difficulty: 3, type: 'mcq',
  q: 'To get each customer\'s latest order you write SELECT DISTINCT ON (customer_id) * FROM orders ORDER BY ... Which ORDER BY is required for a correct result?',
  options: ['ORDER BY order_date DESC', 'ORDER BY customer_id, order_date DESC', 'ORDER BY order_date DESC, customer_id', 'No ORDER BY is needed; DISTINCT ON always keeps the newest row'], answer: 1,
  explain: 'DISTINCT ON keeps the FIRST row of each group in sort order, and its expressions must match the leftmost ORDER BY expressions (otherwise PostgreSQL errors). The remaining ORDER BY keys decide which row is "first" — here the newest order_date. Add id DESC as a tie-breaker for determinism. DISTINCT ON is a PostgreSQL extension to the SQL standard.' },
{ topic: 'SQL', difficulty: 3, type: 'scenario',
  q: 'In INSERT INTO products (sku, ..., stock) VALUES (...) ON CONFLICT (sku) DO UPDATE SET stock = products.stock + EXCLUDED.stock, what is EXCLUDED?',
  options: ['The existing row in the table that caused the conflict', 'The row that was proposed for insertion and rejected because of the conflict', 'A system table listing rejected rows', 'Rows deleted by the statement'], answer: 1,
  explain: 'EXCLUDED is a special pseudo-table holding the row you tried to insert. The table name (or alias) refers to the existing row. So products.stock + EXCLUDED.stock adds the incoming quantity to the current one atomically. ON CONFLICT needs a unique index or constraint matching the conflict target (here the UNIQUE on sku).' },

/* ========================= Database design (8) ========================= */
{ topic: 'Database design', difficulty: 1, type: 'mcq',
  q: 'A table stores tags as a comma-separated string: \'sale,new,summer\'. Which normal form does this violate first?',
  options: ['First normal form (values must be atomic)', 'Second normal form', 'Third normal form', 'Boyce-Codd normal form'], answer: 0,
  explain: '1NF requires each column to hold one atomic value per row. Comma lists cannot be indexed, validated, or joined properly. Model tags with a junction table, or — when you accept the trade-offs — a native text[] (like products.tags) with a GIN index, which PostgreSQL can index and query with @&gt; and &amp;&amp;.' },
{ topic: 'Database design', difficulty: 1, type: 'tf',
  q: 'Declaring a FOREIGN KEY in PostgreSQL automatically creates an index on the referencing (child) column.',
  answer: false,
  explain: 'PostgreSQL requires a unique index on the REFERENCED (parent) columns, but never indexes the referencing columns automatically. Without an index on, say, orders.customer_id, every DELETE/UPDATE of a customer scans orders to check the constraint, and joins from customer to orders are slow. Index FK columns unless you have measured that you do not need it.' },
{ topic: 'Database design', difficulty: 2, type: 'design',
  q: 'Employees work on many projects and projects have many employees, each with a role and allocation. Best model?',
  options: ['A project_ids int[] column on employees', 'A junction table employee_projects(employee_id FK, project_id FK, role, allocation_pct) with PRIMARY KEY (employee_id, project_id)', 'Columns project1_id, project2_id, project3_id on employees', 'A jsonb column on projects holding employee objects'], answer: 1,
  explain: 'A many-to-many relationship with its own attributes is a junction (associative) table. The composite PK prevents duplicates and serves lookups by employee; add an index on (project_id) for lookups the other way. Arrays and jsonb cannot enforce foreign keys and make the relationship attributes awkward to query.' },
{ topic: 'Database design', difficulty: 2, type: 'mcq',
  q: 'Which type should store invoice amounts like 1999.99?',
  options: ['real', 'double precision', 'numeric(12,2)', 'money stored as text'], answer: 2,
  explain: 'numeric is exact decimal arithmetic; real/double precision are binary floating point, so 0.1 + 0.2 is not exactly 0.3 and sums drift. numeric is slower than float but correctness matters for money. (Some teams store integer cents in bigint for speed — also exact.) The money type is locale-dependent and generally discouraged.' },
{ topic: 'Database design', difficulty: 2, type: 'design',
  q: 'Users in India, the UK and the USA place orders. Which column type for order_date?',
  options: ['timestamp (without time zone) holding local wall-clock time', 'timestamptz', 'date plus a separate time column', 'text in ISO-8601 format'], answer: 1,
  explain: 'timestamptz stores an absolute instant (internally UTC) and converts to the session TimeZone on output, so 10:00 in Mumbai and 04:30 in London compare correctly. timestamp without time zone is just a wall-clock reading with no zone — ambiguous across regions and DST changes. Neither type actually stores the original zone; keep a separate column if you need it.' },
{ topic: 'Database design', difficulty: 2, type: 'bug',
  q: 'users.email has a plain UNIQUE constraint, yet both \'Asha@Rodic.com\' and \'asha@rodic.com\' were inserted. Best fix?',
  options: ['Add a CHECK (email = email)', 'Create a unique index on lower(email) (or use the citext extension type)', 'Make email the primary key', 'Use a trigger to uppercase the email'], answer: 1,
  explain: 'Text comparison is case-sensitive, so the two strings are different values. CREATE UNIQUE INDEX ON users (lower(email)) enforces case-insensitive uniqueness, and queries must then filter on lower(email) to use it. Alternatively the citext extension provides a case-insensitive text type. Note: email local parts are technically case-sensitive, but virtually every application treats them as insensitive.' },
{ topic: 'Database design', difficulty: 3, type: 'design',
  q: 'A B2B SaaS has ~3,000 tenants, most small, sharing one PostgreSQL cluster. Which design scales best operationally?',
  options: ['One database per tenant', 'One schema per tenant with identical tables', 'Shared tables with a tenant_id column, composite indexes leading with tenant_id, and Row Level Security policies', 'One giant table with no tenant column; filter in the application'], answer: 2,
  explain: 'Thousands of databases or schemas multiply catalog size, migrations, connection pools and autovacuum work. Shared tables with tenant_id keep one schema to migrate, one pool, and let indexes like (tenant_id, created_at) serve per-tenant queries. RLS adds defense-in-depth against a forgotten WHERE tenant_id = ... Large "whale" tenants can later be moved out or the design sharded by tenant_id (e.g. with the Citus extension).' },
{ topic: 'Database design', difficulty: 3, type: 'scenario',
  q: 'Products in different categories have different attributes (speakers: wattage; desks: material). Filtering is mostly on brand and category. Best approach?',
  options: ['EAV table (product_id, attr_name, attr_value text)', 'Regular columns for common, frequently filtered fields (category, brand, price) plus a jsonb attributes column with a GIN index for the variable rest', 'One table per category', 'Store everything in a single jsonb column, including price'], answer: 1,
  explain: 'Hybrid modelling keeps typed, constrained, well-indexed columns for what you filter and aggregate on, and uses jsonb for genuinely variable data. A GIN index supports containment queries like attributes @&gt; \'{"color":"black"}\'. EAV loses typing and needs one self-join per attribute; all-jsonb loses constraints and good statistics on hot fields.' },

/* ============================== Indexes (9) ============================== */
{ topic: 'Indexes', difficulty: 1, type: 'mcq',
  q: 'Which index type does CREATE INDEX use when you do not specify USING?',
  options: ['Hash', 'GIN', 'B-tree', 'BRIN'], answer: 2,
  explain: 'B-tree is the default and supports =, &lt;, &lt;=, &gt;, &gt;=, BETWEEN, IN, IS NULL, ORDER BY and anchored LIKE \'abc%\' (with C collation or text_pattern_ops). Other types (GIN, GiST, BRIN, Hash, SP-GiST) solve specific problems.' },
{ topic: 'Indexes', difficulty: 1, type: 'index',
  q: 'This is the top query on the "My orders" page and it does a Seq Scan on 5,000+ rows: SELECT * FROM orders WHERE customer_id = $1. Which index?',
  options: ['CREATE INDEX ON orders (status)', 'CREATE INDEX ON orders (customer_id)', 'CREATE INDEX ON customers (id)', 'CREATE INDEX ON orders USING brin (customer_id)'], answer: 1,
  explain: 'An equality predicate on a selective column is the classic B-tree case. customers(id) is already indexed by its PK. BRIN only helps when values correlate with physical row order, which customer_id does not. orders(customer_id) is deliberately missing in company_db — and it is also a foreign key column, which should usually be indexed anyway.' },
{ topic: 'Indexes', difficulty: 2, type: 'index',
  q: 'Query: SELECT * FROM orders WHERE customer_id = $1 ORDER BY order_date DESC LIMIT 10. Best single index?',
  options: ['(order_date, customer_id)', '(customer_id, order_date)', 'Two separate indexes on customer_id and order_date', 'A GIN index on (customer_id, order_date)'], answer: 1,
  explain: 'Put equality columns first, then the sort column. With (customer_id, order_date) PostgreSQL jumps to the customer\'s entries, which are already sorted by date; it reads them backwards and stops after 10 — no sort node. (order_date, customer_id) puts the sort column first so the customer\'s entries are scattered across the whole index. Two separate indexes cannot deliver the ordering for the combined condition.' },
{ topic: 'Indexes', difficulty: 2, type: 'tf',
  q: 'A plain B-tree index on users(email) can be used for WHERE lower(email) = \'x@y.com\'.',
  answer: false,
  explain: 'The index stores email, not lower(email); applying a function to the column hides it from the index. Create an expression index — CREATE INDEX ON users (lower(email)) — and write the predicate exactly the same way. Expression indexes require IMMUTABLE functions.' },
{ topic: 'Indexes', difficulty: 2, type: 'index',
  q: 'Frequent query: SELECT * FROM products WHERE attributes @> \'{"brand":"Sony"}\'. Which index fits?',
  options: ['B-tree on attributes', 'GIN on attributes (jsonb_ops or jsonb_path_ops)', 'Hash on attributes', 'BRIN on attributes'], answer: 1,
  explain: 'GIN is an inverted index: it maps keys/values inside the jsonb document to rows, which is exactly what containment (@&gt;) needs. jsonb_path_ops is smaller and faster for @&gt; but does not support key-existence operators (?, ?|, ?&amp;). A B-tree on the whole document only helps for equality of the entire value.' },
{ topic: 'Indexes', difficulty: 2, type: 'index',
  q: 'Search box: SELECT * FROM products WHERE name ILIKE \'%phone%\'. Which index can serve it?',
  options: ['B-tree on name', 'B-tree on lower(name)', 'GIN on name gin_trgm_ops (pg_trgm extension)', 'No index can ever help a leading wildcard'], answer: 2,
  explain: 'A leading wildcard defeats B-tree ordering. The pg_trgm extension (contrib, not core) splits text into 3-character trigrams; a GIN (or GiST) trigram index can answer LIKE/ILIKE \'%...%\' and similarity searches. Requires CREATE EXTENSION pg_trgm. For word-based search, full-text search with tsvector is usually better.' },
{ topic: 'Indexes', difficulty: 3, type: 'mcq',
  q: 'Which statement about CREATE INDEX CONCURRENTLY is TRUE?',
  options: ['It is faster than a normal CREATE INDEX', 'It cannot run inside a transaction block, and if it fails it leaves an INVALID index that you must drop and retry', 'It blocks INSERT/UPDATE/DELETE but not SELECT', 'It works only on empty tables'], answer: 1,
  explain: 'CONCURRENTLY takes a SHARE UPDATE EXCLUSIVE lock (writes continue), scans the table twice and waits for older transactions, so it is slower. Because it commits in stages it cannot run inside BEGIN...COMMIT. On failure (e.g. a duplicate for a UNIQUE index, deadlock, cancel) the index remains marked invalid (pg_index.indisvalid = false): it is maintained on writes but never used for reads — drop it and retry.' },
{ topic: 'Indexes', difficulty: 3, type: 'index',
  q: 'An append-only sensor table has 2 billion rows; rows arrive in time order and queries filter on recorded_at ranges. You need a tiny index. Best choice?',
  options: ['B-tree on recorded_at', 'BRIN on recorded_at', 'GIN on recorded_at', 'Hash on recorded_at'], answer: 1,
  explain: 'BRIN stores a min/max summary per block range (128 pages by default), so the index is kilobytes to a few megabytes instead of tens of GB, and range queries skip non-matching ranges. It only works when the column correlates with physical order — perfect for append-only time series. A B-tree would also work but costs far more space and write overhead.' },
{ topic: 'Indexes', difficulty: 3, type: 'optimize',
  q: 'A jobs table has 50M rows; only ~5,000 are status = \'pending\'. Workers run the query below constantly. Best index?',
  code: `SELECT id FROM jobs
WHERE status = 'pending'
ORDER BY created_at
LIMIT 10;`,
  options: ['CREATE INDEX ON jobs (status)', 'CREATE INDEX ON jobs (created_at) WHERE status = \'pending\'', 'CREATE INDEX ON jobs (status, created_at, id, payload)', 'CREATE INDEX ON jobs USING hash (status)'], answer: 1,
  explain: 'A partial index contains only rows matching its WHERE clause — about 5,000 entries instead of 50M — so it is tiny, stays in cache, and is cheap to maintain. Ordering by created_at inside it returns the oldest pending jobs without a sort. The query predicate must imply the index predicate for the planner to use it.' },

/* ============================ Transactions (9) ============================ */
{ topic: 'Transactions', difficulty: 1, type: 'mcq',
  q: 'A transfer debits account A and credits account B. The server crashes between the two UPDATEs inside one transaction. Which ACID property guarantees neither change survives?',
  options: ['Atomicity', 'Consistency', 'Isolation', 'Durability'], answer: 0,
  explain: 'Atomicity means all-or-nothing: an uncommitted transaction leaves no trace after crash recovery, because its changes are never marked committed in the commit log (pg_xact). Durability is the opposite guarantee: once COMMIT returns, the changes survive a crash (via WAL flushed to disk).' },
{ topic: 'Transactions', difficulty: 1, type: 'tf',
  q: 'Outside an explicit BEGIN, each SQL statement in PostgreSQL runs in its own transaction that commits automatically if it succeeds.',
  answer: true,
  explain: 'PostgreSQL is "autocommit" by default: a single statement is an implicit transaction. Group statements with BEGIN ... COMMIT when they must succeed or fail together. Note psql\'s \\set AUTOCOMMIT off and some drivers change this client-side behaviour.' },
{ topic: 'Transactions', difficulty: 2, type: 'mcq',
  q: 'What is PostgreSQL\'s default transaction isolation level?',
  options: ['Read Uncommitted', 'Read Committed', 'Repeatable Read', 'Serializable'], answer: 1,
  explain: 'Read Committed: each statement sees a fresh snapshot of data committed before that statement began. Requesting Read Uncommitted in PostgreSQL actually gives Read Committed — dirty reads are never possible. Repeatable Read uses one snapshot for the whole transaction; Serializable adds SSI conflict detection.' },
{ topic: 'Transactions', difficulty: 2, type: 'predict',
  q: 'What happens at the last line?',
  code: `BEGIN;
INSERT INTO departments (name) VALUES ('Legal');
SELECT 1/0;                      -- ERROR: division by zero
INSERT INTO departments (name) VALUES ('Audit');
COMMIT;`,
  options: ['Legal and Audit are both committed', 'Only Legal is committed', 'The second INSERT fails with "current transaction is aborted", and COMMIT actually performs a ROLLBACK — nothing is saved', 'COMMIT raises an error and the session disconnects'], answer: 2,
  explain: 'After any error, the transaction is in an aborted state: every further command fails with "current transaction is aborted, commands ignored until end of transaction block". COMMIT on an aborted transaction reports ROLLBACK. To recover from an expected error mid-transaction, use a SAVEPOINT and ROLLBACK TO SAVEPOINT.' },
{ topic: 'Transactions', difficulty: 2, type: 'mcq',
  q: 'Inside a transaction you run SAVEPOINT s1; then an UPDATE; then ROLLBACK TO SAVEPOINT s1. What is the state?',
  options: ['The whole transaction is rolled back and ended', 'Only work after s1 is undone; the transaction stays open and earlier work is kept', 'The UPDATE is committed', 'The savepoint is released and the UPDATE kept'], answer: 1,
  explain: 'ROLLBACK TO SAVEPOINT undoes changes made after the savepoint and clears an aborted state, while the outer transaction continues. Savepoints are implemented as subtransactions; using thousands of them per transaction can hurt performance (subtransaction cache overflow, pg_subtrans lookups).' },
{ topic: 'Transactions', difficulty: 2, type: 'scenario',
  q: 'Two checkout requests each run SELECT stock FROM products WHERE id = 7 (both see 1), then UPDATE products SET stock = 0 WHERE id = 7. Two units are sold, one existed. Which fix is correct and simplest?',
  options: ['Add an index on products.stock', 'UPDATE products SET stock = stock - 1 WHERE id = 7 AND stock > 0 RETURNING stock — and treat zero rows updated as "sold out"', 'Run both requests at Read Uncommitted', 'Add a 100 ms sleep between SELECT and UPDATE'], answer: 1,
  explain: 'This is a lost update caused by read-modify-write in application code. A single conditional UPDATE is atomic: the second transaction waits for the row lock, then re-checks stock &gt; 0 against the new row version and updates nothing. Alternatives: SELECT ... FOR UPDATE before the update, or Serializable isolation with retries.' },
{ topic: 'Transactions', difficulty: 3, type: 'mcq',
  q: 'Your service switches to SERIALIZABLE isolation. What MUST the application now do?',
  options: ['Nothing; Serializable never raises errors', 'Retry transactions that fail with SQLSTATE 40001 (serialization_failure)', 'Take explicit table locks before every query', 'Disable autovacuum'], answer: 1,
  explain: 'PostgreSQL implements Serializable with Serializable Snapshot Isolation: it lets transactions run optimistically and aborts one when it detects a dangerous dependency pattern. Correct apps wrap the whole transaction in a retry loop for 40001 (and 40P01 deadlocks). Keep serializable transactions short and mark read-only ones READ ONLY to reduce false positives.' },
{ topic: 'Transactions', difficulty: 3, type: 'scenario',
  q: 'Logs show "ERROR: deadlock detected". Transaction A updates account 1 then 2; transaction B updates account 2 then 1. Best permanent fix?',
  options: ['Increase deadlock_timeout to 60s', 'Always lock/update rows in a consistent order (e.g. ascending id) in every code path', 'Use Read Uncommitted', 'Restart PostgreSQL nightly'], answer: 1,
  explain: 'A deadlock needs a cycle of waits. If every transaction acquires locks in the same global order, no cycle can form. PostgreSQL checks for deadlocks after deadlock_timeout (default 1s) and aborts one victim with SQLSTATE 40P01; raising the timeout only delays detection. Retrying the victim is still good practice.' },
{ topic: 'Transactions', difficulty: 3, type: 'mcq',
  q: 'Ten worker processes pull jobs from a queue table. Which query lets each worker grab a different job without blocking the others?',
  options: ['SELECT ... ORDER BY id LIMIT 1 FOR UPDATE', 'SELECT ... ORDER BY id LIMIT 1 FOR UPDATE SKIP LOCKED', 'LOCK TABLE jobs IN ACCESS EXCLUSIVE MODE', 'SELECT ... ORDER BY id LIMIT 1 FOR SHARE'], answer: 1,
  explain: 'FOR UPDATE alone makes every worker queue behind the first locked row. SKIP LOCKED tells each worker to skip rows already locked by others, so they claim different jobs in parallel. Typical pattern: UPDATE jobs SET status=\'running\' WHERE id = (SELECT id FROM jobs WHERE status=\'pending\' ORDER BY id LIMIT 1 FOR UPDATE SKIP LOCKED) RETURNING *.' },

/* ================================ MVCC (8) ================================ */
{ topic: 'MVCC', difficulty: 1, type: 'mcq',
  q: 'What physically happens when PostgreSQL executes UPDATE employees SET salary = salary * 1.1 WHERE id = 5?',
  options: ['The row is overwritten in place', 'A new row version (tuple) is written and the old version is marked as deleted by this transaction (xmax); VACUUM removes it later', 'The old version is copied to an undo log', 'The page is rewritten and the old one discarded immediately'], answer: 1,
  explain: 'PostgreSQL MVCC keeps old row versions in the table itself (no undo log, unlike Oracle/MySQL InnoDB). Concurrent readers with older snapshots still see the old version. Once no snapshot can see it, it is a dead tuple and VACUUM reclaims the space. This is why update-heavy tables need healthy vacuuming.' },
{ topic: 'MVCC', difficulty: 1, type: 'tf',
  q: 'In PostgreSQL, a long SELECT blocks concurrent UPDATEs of the rows it is reading.',
  answer: false,
  explain: 'Readers never block writers and writers never block readers: the SELECT reads the row versions visible to its snapshot while the UPDATE creates new versions. Only writers to the same row block each other (row locks), and DDL takes table-level locks that conflict with reads.' },
{ topic: 'MVCC', difficulty: 2, type: 'mcq',
  q: 'What do the hidden system columns xmin and xmax of a row version hold?',
  options: ['The minimum and maximum value of the row', 'xmin: ID of the transaction that created this version; xmax: ID of the transaction that deleted/updated (or locked) it, or 0', 'The first and last page of the table', 'Snapshot timestamps in microseconds'], answer: 1,
  explain: 'Visibility rules compare xmin/xmax against a snapshot (xmin horizon, running transactions) and commit status from pg_xact. You can see them: SELECT xmin, xmax, ctid, * FROM departments. A non-zero xmax on a live row often means the row was locked (e.g. SELECT FOR UPDATE) or the deleting transaction aborted.' },
{ topic: 'MVCC', difficulty: 2, type: 'mcq',
  q: 'Which statement about plain VACUUM (not FULL) is correct?',
  options: ['It takes an ACCESS EXCLUSIVE lock and rewrites the table', 'It makes dead tuple space reusable, updates the visibility map and free space map, and runs alongside normal reads and writes', 'It always shrinks the data files on disk to the minimum size', 'It rebuilds all indexes from scratch'], answer: 1,
  explain: 'Plain VACUUM takes SHARE UPDATE EXCLUSIVE (compatible with DML), marks space reusable for future rows, and can only return space to the OS by truncating empty pages at the end of the table. VACUUM FULL rewrites the table compactly but holds ACCESS EXCLUSIVE for the whole run — blocking even SELECTs.' },
{ topic: 'MVCC', difficulty: 2, type: 'predict',
  q: 'Department 1 has ctid (0,1). You run the statement below, which does not change any value. What is its ctid afterwards?',
  code: `UPDATE departments SET budget = budget WHERE id = 1;
SELECT ctid FROM departments WHERE id = 1;`,
  options: ['Still (0,1) because nothing changed', 'A different ctid, because every UPDATE writes a new row version', 'NULL', 'The UPDATE is skipped and raises a notice'], answer: 1,
  explain: 'PostgreSQL does not compare old and new values; an UPDATE always creates a new tuple (possibly on the same page as a HOT update, e.g. (0,9)). "No-op" updates therefore still generate WAL and dead tuples. Add WHERE budget IS DISTINCT FROM new_value, or the built-in suppress_redundant_updates_trigger(), to avoid them.' },
{ topic: 'MVCC', difficulty: 3, type: 'mcq',
  q: 'A HOT (heap-only tuple) update avoids touching indexes. When is HOT possible?',
  options: ['Always, for every UPDATE', 'When no indexed column changes and the new version fits on the same heap page', 'Only for tables without a primary key', 'Only when the table is UNLOGGED'], answer: 1,
  explain: 'HOT chains the new version from the old one inside the same page, so indexes keep pointing at the original line pointer. Lowering fillfactor (e.g. 80-90) on update-heavy tables leaves free space for HOT. Check n_tup_hot_upd vs n_tup_upd in pg_stat_user_tables. Indexing a frequently updated column (like last_login) disables HOT for those updates.' },
{ topic: 'MVCC', difficulty: 3, type: 'scenario',
  q: 'Dead tuples keep growing on every table even though autovacuum runs constantly. pg_stat_activity shows a session "idle in transaction" for 6 hours. What is happening?',
  options: ['Autovacuum is disabled', 'The old open transaction holds back the xmin horizon, so VACUUM cannot remove any tuple that became dead after it started', 'The session is holding an exclusive lock on every table', 'Statistics are stale'], answer: 1,
  explain: 'VACUUM may only remove versions invisible to every snapshot. A forgotten transaction (or a stale replication slot, an orphaned prepared transaction, or a standby with hot_standby_feedback) pins the horizon cluster-wide. Terminate it (pg_terminate_backend), fix the application, and set idle_in_transaction_session_timeout as a guard.' },
{ topic: 'MVCC', difficulty: 3, type: 'mcq',
  q: 'Why must every table eventually be vacuumed even if it never has UPDATEs or DELETEs?',
  options: ['To rebuild statistics for the planner', 'To freeze old tuples so 32-bit transaction IDs can wrap around safely', 'To compress TOAST data', 'To rotate WAL files'], answer: 1,
  explain: 'Transaction IDs are 32-bit; comparisons work in a window of about 2 billion. VACUUM marks old tuples as frozen ("visible to everyone"), so their xmin no longer matters. When a table\'s age(relfrozenxid) exceeds autovacuum_freeze_max_age (default 200 million), an anti-wraparound autovacuum runs even if autovacuum is disabled. If freezing falls too far behind, PostgreSQL stops assigning new XIDs to protect data.' },

/* ============================= Performance (9) ============================= */
{ topic: 'Performance', difficulty: 1, type: 'mcq',
  q: 'What is the key difference between EXPLAIN and EXPLAIN ANALYZE?',
  options: ['No difference; ANALYZE just adds colours', 'EXPLAIN shows the estimated plan; EXPLAIN ANALYZE actually executes the query and adds real row counts and timings', 'EXPLAIN ANALYZE updates table statistics', 'EXPLAIN works only for SELECT'], answer: 1,
  explain: 'EXPLAIN only plans. EXPLAIN ANALYZE runs the statement and reports actual time, rows and loops per node; add BUFFERS to see cache hits vs reads (in PostgreSQL 18, BUFFERS is included by default with ANALYZE). Comparing estimated vs actual rows is the fastest way to spot bad statistics.' },
{ topic: 'Performance', difficulty: 1, type: 'tf',
  q: 'Running EXPLAIN ANALYZE DELETE FROM audit_logs WHERE ... actually deletes the rows.',
  answer: true,
  explain: 'EXPLAIN ANALYZE executes the statement for real, including its side effects. Wrap data-modifying statements in BEGIN; EXPLAIN ANALYZE ...; ROLLBACK; when you only want the plan and timings.' },
{ topic: 'Performance', difficulty: 2, type: 'predict',
  q: 'What does this plan most strongly suggest?',
  code: `Seq Scan on orders  (cost=0.00..105.50 rows=4 width=40)
                    (actual time=0.010..0.912 rows=9 loops=1)
  Filter: (customer_id = 42)
  Rows Removed by Filter: 4991`,
  options: ['The statistics are badly wrong', 'A selective filter is applied by scanning every row: an index on orders(customer_id) is missing', 'The query is CPU-bound on sorting', 'The table needs VACUUM FULL'], answer: 1,
  explain: 'The scan reads 5,000 rows to keep 9 — "Rows Removed by Filter" dwarfs the output. Estimates (4) and actuals (9) are close, so statistics are fine. An index on customer_id turns this into an Index Scan or Bitmap Heap Scan; at millions of rows the difference is milliseconds vs seconds.' },
{ topic: 'Performance', difficulty: 2, type: 'mcq',
  q: 'A plan node shows rows=1 estimated but actual rows=48000, and the planner picked a Nested Loop that runs for minutes. First thing to do?',
  options: ['Increase shared_buffers', 'Run ANALYZE on the tables (and if needed raise the column statistics target or add CREATE STATISTICS for correlated columns)', 'SET enable_nestloop = off globally', 'Rebuild all indexes'], answer: 1,
  explain: 'Bad estimates cause bad join choices. ANALYZE refreshes histograms and most-common values; ALTER TABLE ... ALTER COLUMN ... SET STATISTICS 1000 gives finer histograms; extended statistics (CREATE STATISTICS ... (dependencies, ndistinct, mcv)) fix correlated-column misestimates. Disabling planner methods globally is a blunt instrument that hurts other queries.' },
{ topic: 'Performance', difficulty: 2, type: 'optimize',
  q: 'This query cannot use an index on order_date. Best rewrite?',
  code: `SELECT * FROM orders
WHERE date(order_date) = '2025-01-15';`,
  options: ['WHERE order_date::text LIKE \'2025-01-15%\'', 'WHERE order_date >= \'2025-01-15\' AND order_date < \'2025-01-16\'', 'WHERE extract(day FROM order_date) = 15', 'Add ORDER BY order_date'], answer: 1,
  explain: 'Wrapping the column in a function makes the predicate non-sargable. A half-open range on the raw column uses a B-tree on order_date and handles any time of day. Bonus subtlety: order_date is timestamptz, so date(order_date) depends on the session TimeZone; that is why it is not IMMUTABLE and cannot even be used in an expression index.' },
{ topic: 'Performance', difficulty: 2, type: 'optimize',
  q: 'The admin grid pages through orders with LIMIT 50 OFFSET 200000 and deep pages are slow. Best fix?',
  code: `SELECT id, order_date, total_amount
FROM orders
ORDER BY order_date DESC, id DESC
LIMIT 50 OFFSET 200000;`,
  options: ['Increase work_mem', 'Keyset pagination: WHERE (order_date, id) < ($last_date, $last_id) ORDER BY order_date DESC, id DESC LIMIT 50, with an index on (order_date, id)', 'Use OFFSET with a bigger LIMIT', 'Cache COUNT(*) in a table'], answer: 1,
  explain: 'OFFSET still generates and discards every skipped row, so cost grows linearly with page number. Keyset (seek) pagination continues from the last seen key: the row-value comparison uses the composite index and each page costs the same, regardless of depth. Trade-off: no random "jump to page 4000".' },
{ topic: 'Performance', difficulty: 3, type: 'mcq',
  q: 'EXPLAIN ANALYZE shows "Sort Method: external merge  Disk: 180MB". What does it mean and what is the usual remedy?',
  options: ['The table is too big for shared_buffers; increase shared_buffers', 'The sort did not fit in work_mem and spilled to temp files; raise work_mem for that session/query (or avoid the sort with an index)', 'The disk is failing', 'The index is corrupt'], answer: 1,
  explain: 'work_mem is the memory limit per sort/hash operation (each node, each parallel worker; hash nodes may use work_mem × hash_mem_multiplier). A global large value multiplied by many connections and nodes can exhaust RAM, so raise it per session (SET work_mem = \'256MB\') for heavy reports, or remove the sort with an index that already provides the order.' },
{ topic: 'Performance', difficulty: 3, type: 'mcq',
  q: 'The database is "slow" and you do not know which queries are responsible. Where do you start?',
  options: ['pg_stat_statements ordered by total_exec_time (an extension that must be in shared_preload_libraries)', 'Read the table definitions', 'VACUUM FULL every table', 'Increase max_connections'], answer: 0,
  explain: 'pg_stat_statements (contrib extension, not enabled by default) aggregates every normalized query with calls, total/mean time, rows and buffer usage. Sorting by total_exec_time finds what consumes the most server time overall — often a fast query called millions of times rather than one slow report. Then EXPLAIN (ANALYZE, BUFFERS) the top offenders.' },
{ topic: 'Performance', difficulty: 3, type: 'scenario',
  q: 'An ORM page lists 500 orders and then issues one query per order to load its items: 501 round trips, 900 ms. Best fix?',
  options: ['Add more CPU cores to the database server', 'Load items in one query: WHERE order_id = ANY($1::bigint[]) (or a JOIN), i.e. eager loading', 'Raise max_connections so queries run in parallel', 'Add an index on order_items(quantity)'], answer: 1,
  explain: 'This is the N+1 query problem: per-query network latency and overhead dominate, not the database work. Batch loading turns 500 round trips into one (the ORM\'s include/preload feature usually does this). The existing idx_order_items_order makes the batched lookup fast.' },

/* ============================== Security (8) ============================== */
{ topic: 'Security', difficulty: 1, type: 'mcq',
  q: 'What is the primary defence against SQL injection?',
  options: ['Escaping quotes by hand with replace()', 'Parameterized queries / bind parameters ($1, $2) so user input is never parsed as SQL', 'Hiding error messages', 'Using stored procedures for everything'], answer: 1,
  explain: 'With bind parameters the SQL text and the values travel separately; the value can never change the statement\'s structure. Stored procedures that build dynamic SQL by concatenation are still injectable — inside PL/pgSQL use EXECUTE ... USING or format() with %I / %L.' },
{ topic: 'Security', difficulty: 1, type: 'tf',
  q: 'A pg_hba.conf line with method "trust" lets matching clients connect as any database user without a password.',
  answer: true,
  explain: 'trust skips authentication entirely: anyone who can reach that address/socket can connect as any role, including superuser. Use scram-sha-256 for password logins (or cert / GSSAPI), and reserve peer for local OS-user mapping on the Unix socket.' },
{ topic: 'Security', difficulty: 2, type: 'mcq',
  q: 'Which password authentication method should production use?',
  options: ['password (clear text)', 'md5', 'scram-sha-256', 'trust with a firewall'], answer: 2,
  explain: 'SCRAM-SHA-256 never sends the password, resists replay, and stores a salted, iterated verifier. password_encryption defaults to scram-sha-256 since PostgreSQL 14, and MD5 password support is deprecated as of PostgreSQL 18. Migrate by setting password_encryption, re-setting each password, then switching pg_hba.conf lines.' },
{ topic: 'Security', difficulty: 2, type: 'design',
  q: 'A BI dashboard needs read access to orders, customers and products only. Which setup follows least privilege?',
  options: ['Give the BI tool the postgres superuser', 'CREATE ROLE bi_reader LOGIN ...; GRANT CONNECT on the database; GRANT USAGE ON SCHEMA public; GRANT SELECT ON orders, customers, products', 'GRANT ALL ON ALL TABLES IN SCHEMA public TO bi_reader', 'Make bi_reader the owner of those tables'], answer: 1,
  explain: 'Grant only what is needed: CONNECT to the database, USAGE on the schema, SELECT on specific tables (or columns). Owners can ALTER/DROP their tables and bypass RLS, and superusers bypass every check. Consider a dedicated read replica, a statement_timeout on the role, and ALTER ROLE bi_reader SET default_transaction_read_only = on.' },
{ topic: 'Security', difficulty: 2, type: 'mcq',
  q: 'What changed about the public schema in PostgreSQL 15?',
  options: ['It was removed', 'Ordinary users (PUBLIC) no longer have CREATE privilege on it by default, and it is owned by pg_database_owner', 'Everything in it became read-only', 'It became the only schema allowed'], answer: 1,
  explain: 'Before 15, any user could create objects in public, enabling search_path tricks against other users. From 15, PUBLIC keeps USAGE but not CREATE in new databases. Upgraded clusters keep their old ACLs, so run REVOKE CREATE ON SCHEMA public FROM PUBLIC yourself on older databases.' },
{ topic: 'Security', difficulty: 3, type: 'bug',
  q: 'RLS is enabled on users with the policy below, yet the application — which connects as the table owner — still sees every tenant\'s rows. Why?',
  code: `ALTER TABLE users ENABLE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON users
  USING (tenant_id = current_setting('app.tenant_id')::int);`,
  options: ['Policies need a WITH CHECK clause to work for SELECT', 'Table owners (and superusers / BYPASSRLS roles) bypass RLS unless you also run ALTER TABLE users FORCE ROW LEVEL SECURITY — better, connect as a non-owner role', 'current_setting cannot be used in policies', 'RLS only applies to UPDATE'], answer: 1,
  explain: 'By default RLS does not apply to the table owner. Production apps should connect with a dedicated non-owner, non-superuser role; FORCE ROW LEVEL SECURITY makes even the owner subject to policies. Superusers and roles with BYPASSRLS always bypass policies.' },
{ topic: 'Security', difficulty: 3, type: 'bug',
  q: 'What is the security flaw in this function?',
  code: `CREATE FUNCTION reset_password(p_user int, p_hash text)
RETURNS void
LANGUAGE sql
SECURITY DEFINER
AS $$ UPDATE users SET password_hash = p_hash WHERE id = p_user $$;`,
  options: ['SQL functions cannot be SECURITY DEFINER', 'It runs with the owner\'s privileges but no fixed search_path, so a caller could create a malicious object in a schema earlier on their search_path; add SET search_path = pg_catalog, public (or schema-qualify) and REVOKE EXECUTE FROM PUBLIC', 'It returns void', 'The parameter names are too short'], answer: 1,
  explain: 'SECURITY DEFINER functions execute as their owner. Unqualified names are resolved via the caller-influenced search_path, which can be hijacked (e.g. a user-created users table or operator in a writable schema). Always pin search_path, schema-qualify objects, and restrict EXECUTE (functions are executable by PUBLIC by default). Also check authorisation inside the function — as written, anyone allowed to call it can reset anyone\'s password.' },
{ topic: 'Security', difficulty: 3, type: 'mcq',
  q: 'You must hash passwords inside PostgreSQL using the pgcrypto extension. Which is correct?',
  options: ['md5(password)', 'crypt(password, gen_salt(\'bf\', 10)) and verify with password_hash = crypt(input, password_hash)', 'encode(digest(password, \'sha256\'), \'hex\')', 'pgp_sym_encrypt(password, \'key\')'], answer: 1,
  explain: 'crypt() with a bcrypt salt (gen_salt(\'bf\', cost)) produces a salted, deliberately slow hash; verification re-hashes the input with the stored hash as the salt. Unsalted fast digests (md5, sha256) are brute-forced quickly; encryption is reversible and wrong for passwords. pgcrypto is a contrib extension (CREATE EXTENSION pgcrypto). Many teams hash in the application instead so plaintext never reaches the database or its logs.' },

/* ============================= Replication (8) ============================= */
{ topic: 'Replication', difficulty: 1, type: 'mcq',
  q: 'What does physical streaming replication send from primary to standby?',
  options: ['SQL statements', 'WAL (write-ahead log) records, producing a byte-for-byte copy of the whole cluster', 'Only changed rows of selected tables', 'Nightly pg_dump files'], answer: 1,
  explain: 'The standby\'s WAL receiver streams WAL from the primary\'s WAL sender and replays it. The standby is a physical copy of every database in the cluster, must run the same major version and architecture, and serves read-only queries when hot_standby = on (the default).' },
{ topic: 'Replication', difficulty: 1, type: 'tf',
  q: 'A hot standby in streaming replication can accept INSERT and UPDATE statements.',
  answer: false,
  explain: 'A standby in recovery is read-only; writes fail with "cannot execute INSERT in a read-only transaction". It becomes writable only after promotion (pg_ctl promote or SELECT pg_promote()). For multi-writer setups you need logical replication with conflict handling or a different architecture.' },
{ topic: 'Replication', difficulty: 2, type: 'mcq',
  q: 'Which is TRUE about logical replication (CREATE PUBLICATION / CREATE SUBSCRIPTION)?',
  options: ['It copies the entire cluster byte for byte', 'It replicates row changes for chosen tables, works across major versions, but does NOT replicate DDL (schema changes)', 'It requires both servers on the same OS and CPU architecture', 'The subscriber is always read-only'], answer: 1,
  explain: 'Logical replication decodes WAL into row-level changes and applies them on a subscriber that is a normal writable database. It is ideal for near-zero-downtime major-version upgrades and selective replication. Schema changes must be applied to the subscriber separately, and tables need a primary key or REPLICA IDENTITY for UPDATE/DELETE. Requires wal_level = logical on the publisher.' },
{ topic: 'Replication', difficulty: 2, type: 'mcq',
  q: 'With synchronous_commit = on and a standby listed in synchronous_standby_names, when does COMMIT return?',
  options: ['Immediately, before WAL is written', 'After the WAL is flushed locally AND the synchronous standby confirms it has flushed it to disk', 'After the standby has replayed and made the change visible', 'After the next checkpoint'], answer: 1,
  explain: 'synchronous_commit = on waits for remote flush, giving zero data loss if the primary dies. remote_apply additionally waits until the change is visible on the standby (read-your-writes on replicas); remote_write waits only for the OS write. The cost is commit latency equal to the network round trip — and if the only sync standby is down, commits hang.' },
{ topic: 'Replication', difficulty: 2, type: 'scenario',
  q: 'Users report stale data on read replicas. How do you measure replication lag?',
  options: ['SELECT count(*) on both servers', 'On the primary: write_lag/flush_lag/replay_lag and LSN differences in pg_stat_replication; on the standby: now() - pg_last_xact_replay_timestamp()', 'Check pg_stat_user_tables.n_dead_tup', 'Compare file sizes in PGDATA'], answer: 1,
  explain: 'pg_stat_replication shows each standby\'s sent/write/flush/replay LSNs and time lags; pg_wal_lsn_diff(pg_current_wal_lsn(), replay_lsn) gives the byte gap. On a standby, now() - pg_last_xact_replay_timestamp() shows time since the last replayed commit (it grows on an idle primary too, so interpret with care).' },
{ topic: 'Replication', difficulty: 3, type: 'scenario',
  q: 'The primary\'s disk fills with WAL in pg_wal. pg_replication_slots shows a slot with active = false whose restart_lsn is days old. Correct response?',
  options: ['Delete files from pg_wal by hand', 'Drop the abandoned slot (SELECT pg_drop_replication_slot(...)) after confirming its consumer is gone, and set max_slot_wal_keep_size to cap retained WAL in future', 'Increase max_wal_size', 'Run VACUUM FULL'], answer: 1,
  explain: 'A replication slot guarantees WAL is retained until its consumer confirms it — forever, if the consumer disappeared. Never delete WAL files manually: that corrupts the cluster. Dropping the slot lets checkpoints recycle WAL. max_slot_wal_keep_size invalidates slots that fall too far behind instead of filling the disk. Abandoned logical slots also hold back the catalog xmin horizon.' },
{ topic: 'Replication', difficulty: 3, type: 'mcq',
  q: 'A user updates their profile (primary) and the next page load reads from an async replica and shows old data. Which fix is correct?',
  options: ['Make all replicas synchronous with synchronous_commit = remote_write', 'Route that user\'s reads to the primary for a short window after a write (or wait until the replica\'s replay LSN passes the write\'s LSN)', 'Increase wal_buffers', 'Use logical replication instead'], answer: 1,
  explain: 'Async replicas are eventually consistent; this "read-your-writes" anomaly is normal. Common patterns: session stickiness to the primary after writes, or capture pg_current_wal_lsn() after the write and only read from a replica whose pg_last_wal_replay_lsn() has passed it. remote_write does not guarantee visibility; only remote_apply would, at a latency cost on every commit.' },
{ topic: 'Replication', difficulty: 3, type: 'mcq',
  q: 'Long analytics queries on a standby keep failing with "canceling statement due to conflict with recovery". What does enabling hot_standby_feedback trade off?',
  options: ['Nothing; it is always free', 'Fewer query cancellations on the standby, but the primary\'s VACUUM must keep row versions the standby still needs, causing bloat on the primary', 'It makes replication synchronous', 'It disables WAL archiving'], answer: 1,
  explain: 'The standby reports its oldest snapshot xmin to the primary, so VACUUM there will not remove rows standby queries might read. Alternatives: raise max_standby_streaming_delay (replay waits, increasing lag), or run long analytics on a dedicated replica or a logical copy.' },

/* ============================ Partitioning (8) ============================ */
{ topic: 'Partitioning', difficulty: 1, type: 'mcq',
  q: 'Which partitioning methods does PostgreSQL declarative partitioning support natively?',
  options: ['RANGE, LIST and HASH', 'Only RANGE', 'RANGE and ROUND_ROBIN', 'KEY and COMPOSITE only'], answer: 0,
  explain: 'PARTITION BY RANGE (dates, ids), LIST (regions, tenants, statuses) and HASH (even spread via MODULUS/REMAINDER). Sub-partitioning is possible by making a partition itself partitioned. Declarative partitioning is core since PostgreSQL 10.' },
{ topic: 'Partitioning', difficulty: 1, type: 'tf',
  q: 'Partitioning a large table makes every query against it faster.',
  answer: false,
  explain: 'Queries that filter on the partition key benefit from pruning; queries that do not must visit every partition and can be slower due to more planning and more index probes. The biggest wins are often operational: dropping old data instantly, per-partition VACUUM and smaller indexes.' },
{ topic: 'Partitioning', difficulty: 2, type: 'mcq',
  q: 'orders_part is partitioned BY RANGE (order_date) monthly. Which query benefits from partition pruning?',
  options: ['WHERE customer_id = 42', 'WHERE order_date >= \'2025-03-01\' AND order_date < \'2025-04-01\'', 'WHERE total_amount > 1000', 'ORDER BY id LIMIT 10'], answer: 1,
  explain: 'Pruning eliminates partitions whose bounds cannot match a predicate on the partition key — here only the March partition is scanned. It happens at plan time for constants and at execution time for parameters and subquery values. Predicates on other columns cannot prune.' },
{ topic: 'Partitioning', difficulty: 2, type: 'bug',
  q: 'Why does this fail?',
  code: `CREATE TABLE events (
  id         bigint PRIMARY KEY,
  created_at timestamptz NOT NULL
) PARTITION BY RANGE (created_at);`,
  options: ['bigint cannot be a primary key', 'A unique constraint/primary key on a partitioned table must include all partition key columns: use PRIMARY KEY (id, created_at)', 'RANGE partitioning does not support timestamptz', 'Partitioned tables cannot have constraints'], answer: 1,
  explain: 'Unique indexes are enforced per partition; PostgreSQL can only guarantee global uniqueness if the partition key is part of the key, so equal keys always land in the same partition. Use PRIMARY KEY (id, created_at). If id must be globally unique alone, rely on the identity/sequence or enforce uniqueness elsewhere.' },
{ topic: 'Partitioning', difficulty: 2, type: 'mcq',
  q: 'Partition p2025_01 is defined FOR VALUES FROM (\'2025-01-01\') TO (\'2025-02-01\'). Where does a row with order_date = \'2025-02-01 00:00\' go?',
  options: ['p2025_01, because TO is inclusive', 'The February partition (or error/default partition if none exists), because the upper bound is exclusive', 'Both partitions', 'It is silently dropped'], answer: 1,
  explain: 'Range bounds are inclusive FROM and exclusive TO, so consecutive partitions share boundary values without overlap or gaps. Always use the next period\'s start as the upper bound, never "2025-01-31 23:59:59".' },
{ topic: 'Partitioning', difficulty: 3, type: 'scenario',
  q: 'Policy: keep 24 months of orders. Every month a job runs DELETE FROM orders WHERE order_date < now() - interval \'24 months\', causing huge WAL, bloat and long vacuums. Better approach?',
  options: ['Run the DELETE more often in smaller batches only', 'Partition by month; each month ALTER TABLE ... DETACH PARTITION ... CONCURRENTLY and then DROP TABLE (or archive) the old partition', 'Use TRUNCATE on the whole table', 'Disable autovacuum during the delete'], answer: 1,
  explain: 'Dropping a partition is a metadata operation: no per-row WAL, no dead tuples, no vacuum. DETACH ... CONCURRENTLY (PostgreSQL 14+) avoids blocking queries on the parent (it cannot run inside a transaction block). You can also archive the detached table with pg_dump before dropping it.' },
{ topic: 'Partitioning', difficulty: 3, type: 'mcq',
  q: 'An INSERT targets a range-partitioned table but no partition covers the value and there is no DEFAULT partition. What happens?',
  options: ['PostgreSQL auto-creates a partition', 'The row goes to the parent table', 'The INSERT fails with "no partition of relation ... found for row"', 'The row is placed in the nearest partition'], answer: 2,
  explain: 'PostgreSQL never auto-creates partitions. Create future partitions ahead of time (cron job or the pg_partman extension) and monitor for missing ones. A DEFAULT partition catches strays, but later creating a partition whose range overlaps rows already in the default requires scanning/moving them under lock.' },
{ topic: 'Partitioning', difficulty: 3, type: 'design',
  q: 'An events table receives 30M rows/day and must keep 2 years. Which partitioning granularity is most reasonable?',
  options: ['Hourly (~17,500 partitions)', 'Daily or weekly (~100-730 partitions), sized so each partition and its indexes are manageable', 'One partition per user', 'No partitioning; just add more indexes'], answer: 1,
  explain: 'Each partition adds planning work, relation-cache memory and lock overhead for queries that cannot prune; tens of thousands of partitions hurt. Too few means huge partitions and coarse retention. Aim for hundreds to low thousands of partitions, matching the granularity to retention and query patterns.' },

/* =============================== Sharding (8) =============================== */
{ topic: 'Sharding', difficulty: 1, type: 'mcq',
  q: 'What is the essential difference between partitioning and sharding?',
  options: ['They are the same thing', 'Partitioning splits a table into pieces inside one PostgreSQL server; sharding distributes data across multiple servers', 'Sharding is only for indexes', 'Partitioning requires multiple servers'], answer: 1,
  explain: 'Partitioning helps manageability and pruning on one node but is still limited by that node\'s CPU, RAM, disk and write throughput. Sharding scales writes and storage horizontally by placing different rows on different machines, at the cost of distributed queries, transactions and operations.' },
{ topic: 'Sharding', difficulty: 1, type: 'tf',
  q: 'Core PostgreSQL includes built-in automatic sharding across multiple servers.',
  answer: false,
  explain: 'Core PostgreSQL has no automatic sharding. Options: the Citus extension (distributed tables over worker nodes), application-level sharding (the app routes by key), or manual setups with postgres_fdw and partitioning. Declarative partitioning alone is single-node.' },
{ topic: 'Sharding', difficulty: 2, type: 'design',
  q: 'A multi-tenant SaaS where almost every query is scoped to one company. Best shard key?',
  options: ['created_at', 'tenant_id (company id)', 'A random UUID per row', 'status'], answer: 1,
  explain: 'Sharding by tenant co-locates all of a tenant\'s rows on one shard, so most queries and transactions touch a single node and joins between tenant tables stay local. Time-based keys concentrate all new writes on one shard; random keys spread data but force every tenant query to fan out to all shards.' },
{ topic: 'Sharding', difficulty: 2, type: 'mcq',
  q: 'Orders are sharded by customer country; India produces 60% of traffic. What problem appears?',
  options: ['Cross-shard joins become impossible', 'A hot shard: one node carries most load and storage while others sit idle', 'Sequences stop working', 'Indexes cannot be created'], answer: 1,
  explain: 'Low-cardinality or skewed keys create hotspots. Good shard keys have high cardinality and even distribution and match the dominant access pattern (e.g. customer_id). Even then, very large individual tenants may need isolating onto their own nodes.' },
{ topic: 'Sharding', difficulty: 2, type: 'mcq',
  q: 'Compared with range-based sharding on customer_id, hash-based sharding...',
  options: ['Makes range scans over customer_id efficient', 'Spreads keys evenly and avoids hotspots for sequential keys, but range queries on the key must hit every shard', 'Requires no routing logic', 'Guarantees zero cross-shard queries'], answer: 1,
  explain: 'Hashing destroys ordering: consecutive ids land on different shards, which balances inserts but turns "customers 1000-2000" into a fan-out. Range sharding keeps ranges together but new (high) ids all hit the last shard. Citus uses hash distribution by default.' },
{ topic: 'Sharding', difficulty: 3, type: 'scenario',
  q: 'A sharded design needs to move money between customers that live on different shards. What is the main concern?',
  options: ['None; each shard commits independently and that is enough', 'Atomicity across nodes requires a distributed commit protocol (two-phase commit) and adds latency and failure modes, so designs try to keep transactions single-shard', 'Indexes cannot be used', 'The WAL must be shared'], answer: 1,
  explain: 'Two independent commits can leave one side applied and the other not. Two-phase commit (PREPARE TRANSACTION / COMMIT PREPARED in core, used internally by Citus) gives atomicity but adds round trips and in-doubt transactions that must be resolved after crashes. Choose shard keys so the common transactions are single-shard; use sagas/outbox patterns where cross-shard flows are unavoidable.' },
{ topic: 'Sharding', difficulty: 3, type: 'mcq',
  q: 'With the Citus extension, orders and order_items are distributed by customer_id. A small countries table is joined by every query. How should it be created?',
  options: ['create_distributed_table(\'countries\', \'id\')', 'create_reference_table(\'countries\') — a full copy on every node so joins stay local', 'Leave it only on the coordinator', 'Store countries as a jsonb column on every row'], answer: 1,
  explain: 'Reference tables are replicated to all nodes, so any shard can join them locally. Distributed tables that share a distribution column and are co-located (create_distributed_table(\'order_items\', \'customer_id\', colocate_with =&gt; \'orders\')) can also join locally. Citus is an extension that turns PostgreSQL into a distributed database; it is not part of core.' },
{ topic: 'Sharding', difficulty: 3, type: 'scenario',
  q: 'An app shards with shard = hash(customer_id) % 4. Growing to 8 servers means rehashing. What design avoids moving most data?',
  options: ['Use % 8 and accept moving ~50% of rows', 'Create many logical shards up front (e.g. 128 or 256) mapped to physical nodes through a lookup table; rebalance by moving whole logical shards', 'Shard by created_at instead', 'Add read replicas'], answer: 1,
  explain: 'With modulo hashing, changing N remaps a large share of keys. Pre-splitting into many small logical shards decouples data placement from server count: adding nodes means moving a subset of logical shards (Citus uses 32 shards per distributed table by default and moves shards online with its rebalancer). Consistent hashing is another approach.' },

/* =============================== pgvector (8) =============================== */
{ topic: 'pgvector', difficulty: 1, type: 'mcq',
  q: 'How do you enable vector similarity search in PostgreSQL?',
  options: ['It is built into core; just use the vector type', 'Install the pgvector extension and run CREATE EXTENSION vector', 'SET enable_vector = on', 'Use the tsvector type'], answer: 1,
  explain: 'pgvector is a third-party open-source extension, not core PostgreSQL. Its SQL name is vector (CREATE EXTENSION vector). It adds vector, halfvec, sparsevec and bit-vector support, distance operators and HNSW / IVFFlat index types. tsvector is unrelated — it is full-text search.' },
{ topic: 'pgvector', difficulty: 1, type: 'tf',
  q: 'In pgvector, a <=> b returns cosine SIMILARITY, so you ORDER BY embedding <=> query DESC to get the nearest neighbours.',
  answer: false,
  explain: '&lt;=&gt; is cosine DISTANCE (1 - cosine similarity), so smaller means more similar and nearest-neighbour queries use ORDER BY ... ASC LIMIT k. Other operators: &lt;-&gt; Euclidean (L2) distance, &lt;#&gt; negative inner product, &lt;+&gt; L1 distance. Indexes only accelerate ascending distance ordering.' },
{ topic: 'pgvector', difficulty: 2, type: 'predict',
  q: 'What does this return (pgvector installed)?',
  code: `SELECT '[1,0]'::vector <-> '[0,1]'::vector AS l2,
       '[1,0]'::vector <=> '[0,1]'::vector AS cosine;`,
  options: ['l2 = 2, cosine = 0', 'l2 ≈ 1.4142, cosine = 1', 'l2 = 1, cosine = 1.4142', 'l2 = 0, cosine = -1'], answer: 1,
  explain: 'L2 distance is sqrt((1-0)² + (0-1)²) = sqrt(2) ≈ 1.4142. The vectors are orthogonal, so cosine similarity is 0 and cosine distance is 1 - 0 = 1. Identical directions give cosine distance 0; opposite directions give 2.' },
{ topic: 'pgvector', difficulty: 2, type: 'index',
  q: 'A new RAG table starts empty and grows continuously; you need high recall and low query latency. Which pgvector index?',
  options: ['IVFFlat created on the empty table', 'HNSW', 'B-tree on the embedding column', 'GIN on the embedding column'], answer: 1,
  explain: 'HNSW builds a navigable graph incrementally, can be created on an empty table and offers a better speed/recall trade-off, at the cost of slower builds and more memory. IVFFlat clusters existing data into lists at build time; created on an empty or tiny table, its centroids are meaningless and recall suffers — build it after loading representative data.' },
{ topic: 'pgvector', difficulty: 2, type: 'bug',
  q: 'The HNSW index is never used by this query. Why?',
  code: `CREATE INDEX ON docs USING hnsw (embedding vector_l2_ops);

SELECT id FROM docs
ORDER BY embedding <=> $1
LIMIT 5;`,
  options: ['HNSW indexes cannot be used with LIMIT', 'The index operator class (vector_l2_ops, for <->) does not match the query operator (<=>, cosine); create the index with vector_cosine_ops', 'The query needs a WHERE clause', 'HNSW needs ANALYZE first'], answer: 1,
  explain: 'An index serves only the distance operator of its operator class: vector_l2_ops ↔ &lt;-&gt;, vector_cosine_ops ↔ &lt;=&gt;, vector_ip_ops ↔ &lt;#&gt;, vector_l1_ops ↔ &lt;+&gt;. Pick the metric your embedding model was trained for (cosine for most text models) and use the same one everywhere.' },
{ topic: 'pgvector', difficulty: 3, type: 'mcq',
  q: 'HNSW search quality is too low (relevant documents missing). Which runtime setting increases recall at the cost of speed?',
  options: ['SET hnsw.ef_search = 100 (default 40)', 'SET work_mem = \'1GB\'', 'SET ivfflat.lists = 1000', 'SET enable_seqscan = off'], answer: 0,
  explain: 'hnsw.ef_search is the size of the candidate list during search; larger means more graph exploration, better recall and slower queries. It also caps how many rows a single index scan can return. For IVFFlat the equivalent is ivfflat.probes (lists is a build-time index option, not a GUC). Build-time HNSW options are m and ef_construction.' },
{ topic: 'pgvector', difficulty: 3, type: 'scenario',
  q: 'SELECT ... WHERE category = \'policy\' ORDER BY embedding <=> $1 LIMIT 10 with an HNSW index often returns only 2-3 rows. Why, and what helps?',
  options: ['A pgvector bug; rebuild the index', 'The index returns ef_search nearest candidates first and the filter is applied afterwards, removing most of them; enable iterative index scans (SET hnsw.iterative_scan = relaxed_order, pgvector 0.8+), raise ef_search, or use partial indexes/partitioning per category', 'LIMIT is not supported with filters', 'Cosine distance cannot be combined with WHERE'], answer: 1,
  explain: 'Approximate indexes do post-filtering: with a selective filter, few of the ~40 candidates survive. pgvector 0.8.0 added iterative index scans that keep scanning until enough rows pass the filter (strict_order or relaxed_order). For a few large categories, a partial HNSW index per category (or list partitioning) gives exact filtered candidate sets; for very selective filters a B-tree on category plus exact distance sort can be faster.' },
{ topic: 'pgvector', difficulty: 3, type: 'mcq',
  q: 'You store 3,072-dimension embeddings and CREATE INDEX ... USING hnsw (embedding vector_cosine_ops) fails. What is the standard fix?',
  options: ['Increase maintenance_work_mem only', 'HNSW/IVFFlat on vector support up to 2,000 dimensions; index a halfvec expression instead (up to 4,000 dims), e.g. USING hnsw ((embedding::halfvec(3072)) halfvec_cosine_ops), or reduce dimensions', 'Switch to a GIN index', 'Store the embedding as jsonb'], answer: 1,
  explain: 'The vector type can store up to 16,000 dimensions but its index types are limited to 2,000. halfvec (16-bit floats) halves storage and can be indexed up to 4,000 dimensions with minimal recall loss; queries must use the same expression (ORDER BY embedding::halfvec(3072) &lt;=&gt; $1::halfvec(3072)). Many embedding APIs also support requesting fewer dimensions.' },

/* ============================= Architecture (8) ============================= */
{ topic: 'Architecture', difficulty: 1, type: 'mcq',
  q: 'How does PostgreSQL handle each client connection?',
  options: ['One thread in a shared thread pool', 'The postmaster starts a dedicated backend process per connection', 'All clients share one process with an event loop', 'Connections are handled by the operating system kernel'], answer: 1,
  explain: 'PostgreSQL uses a process-per-connection model. Each backend has its own memory (work_mem etc.) and costs several MB plus fork/startup time, which is why thousands of direct connections hurt and poolers such as PgBouncer (third-party tool) are standard.' },
{ topic: 'Architecture', difficulty: 1, type: 'tf',
  q: 'PostgreSQL relies only on shared_buffers for caching and does not benefit from the operating system page cache.',
  answer: false,
  explain: 'PostgreSQL reads and writes through the kernel, so the OS page cache acts as a second-level cache (double buffering). That is why shared_buffers is typically ~25% of RAM rather than 80%, and effective_cache_size tells the planner roughly how much shared_buffers plus OS cache is available.' },
{ topic: 'Architecture', difficulty: 2, type: 'mcq',
  q: 'When COMMIT returns successfully (synchronous_commit = on), what has been guaranteed on disk?',
  options: ['All modified data pages have been written to the table files', 'The WAL records for the transaction, including its commit record, have been flushed to durable storage', 'A checkpoint has completed', 'The change has been replicated to every standby'], answer: 1,
  explain: 'Write-ahead logging: changes go to WAL first and only the WAL must be fsynced at commit (sequential and cheap). Dirty data pages stay in shared_buffers and are written later by the background writer, checkpointer or backends. After a crash, recovery replays WAL from the last checkpoint\'s redo point.' },
{ topic: 'Architecture', difficulty: 2, type: 'mcq',
  q: 'Why do teams put PgBouncer (a third-party tool) in transaction pooling mode in front of PostgreSQL?',
  options: ['To encrypt data at rest', 'To multiplex thousands of client connections over a small number of server connections, since each PostgreSQL connection is a full process', 'To replace streaming replication', 'To cache query results'], answer: 1,
  explain: 'In transaction mode a server connection is assigned only for the duration of a transaction. Caveat: session state does not survive across transactions — session-level SET, advisory locks held across transactions, LISTEN, and temp tables break. Protocol-level prepared statements are supported since PgBouncer 1.21 (max_prepared_statements).' },
{ topic: 'Architecture', difficulty: 2, type: 'mcq',
  q: 'What does a checkpoint do?',
  options: ['Deletes old WAL immediately on every commit', 'Flushes all dirty buffers to the data files and records a point from which crash recovery can start, allowing older WAL to be recycled', 'Takes a backup', 'Runs VACUUM on all tables'], answer: 1,
  explain: 'Checkpoints are triggered by checkpoint_timeout (default 5min) or by WAL volume reaching max_wal_size. Spread over checkpoint_completion_target to smooth I/O. Too-frequent checkpoints inflate WAL with full-page images (first change to each page after a checkpoint is logged in full).' },
{ topic: 'Architecture', difficulty: 3, type: 'scenario',
  q: 'You need automatic failover for a 3-node cluster and must avoid split-brain (two primaries). Which approach is standard?',
  options: ['A cron script that runs pg_ctl promote when ping fails', 'Patroni (third-party tool) with a distributed consensus store (etcd/Consul/ZooKeeper) holding the leader lock, plus HAProxy or a VIP to route clients', 'Two primaries with logical replication both ways', 'pg_basebackup every minute'], answer: 1,
  explain: 'Split-brain prevention needs consensus: only the node holding the leader key in the DCS may run as primary, and a node that loses the lock demotes itself. Simple ping scripts promote during network partitions while the old primary is still accepting writes. Patroni also handles re-cloning, pg_rewind and switchovers.' },
{ topic: 'Architecture', difficulty: 3, type: 'mcq',
  q: 'What is required to restore a database to its state at 14:32 yesterday (point-in-time recovery)?',
  options: ['Last night\'s pg_dump file', 'A physical base backup taken before 14:32 plus every archived WAL segment from that backup up to 14:32; restore and set recovery_target_time', 'A streaming replica', 'Only the WAL files'], answer: 1,
  explain: 'PITR replays WAL on top of a base backup (pg_basebackup, pgBackRest, Barman...). Configure restore_command and recovery_target_time and create recovery.signal (PostgreSQL 12+). A logical pg_dump is a single point in time and cannot be rolled forward. A replica copies mistakes (DROP TABLE) instantly, so it is not a backup.' },
{ topic: 'Architecture', difficulty: 3, type: 'design',
  q: 'The business demands RPO = 0 (no committed transaction may ever be lost) if the primary data centre is destroyed. Which setup meets it?',
  options: ['Asynchronous streaming replication to another region', 'Synchronous replication to at least one standby in a different location (synchronous_standby_names, synchronous_commit = on), accepting higher commit latency', 'Nightly backups shipped offsite', 'WAL archiving every 5 minutes'], answer: 1,
  explain: 'Only synchronous replication ensures a commit is durable on another site before the client is told it succeeded. Async replication and WAL archiving lose whatever had not yet been shipped (RPO = seconds to minutes). Use quorum commit (ANY 1 (s1, s2)) with two candidate standbys so one standby outage does not stall all commits.' }
].sort(function (a, b) { return a.difficulty - b.difficulty; });
